var numberOfSteps = function(num) {
    let steps = 0;

    while (num > 0) {
        if (num % 2 === 0) {
            // Even: divide by 2
            num = Math.floor(num / 2);
        } else {
            // Odd: subtract 1
            num--;
        }

        steps++;
    }

    return steps;
};
